/**
 * Response contracts: what the server must send. The port checks every answer against these and
 * the harness shows any mismatch. Regenerate after a backend change (widgets:contract).
 */
import { s, type Infer } from '../../core/shape';

// <contract rbac.new-role.platform-roles>
/** GET /api/admin/rbac/roles → List<Dtos.RbacRoleView> (PlatformRbacController#roles, rbac.role:read). Generated by widgets:contract. */
export const RBAC_NEW_ROLE_PLATFORM_ROLES = s.array(s.object('RbacRoleView', {
  name: s.nullable(s.string()),
  description: s.nullable(s.string()),
  permissions: s.nullable(s.array(s.string())),
  kind: s.nullable(s.string()),
  approval: s.nullable(s.string()),
  seeded: s.boolean(),
  locked: s.boolean(),
  inherits: s.nullable(s.array(s.string())),
  own: s.nullable(s.array(s.string())),
  allRows: s.nullable(s.array(s.string())),
}));
export type RbacNewRolePlatformRoles = Infer<typeof RBAC_NEW_ROLE_PLATFORM_ROLES>;
// </contract rbac.new-role.platform-roles>

// <contract rbac.new-role.platform-create>
/** POST /api/admin/rbac/roles → Dtos.RbacRoleView (PlatformRbacController#createRole, rbac.role:create). Generated by widgets:contract. */
export const RBAC_NEW_ROLE_PLATFORM_CREATE = s.object('RbacRoleView', {
  name: s.nullable(s.string()),
  description: s.nullable(s.string()),
  permissions: s.nullable(s.array(s.string())),
  kind: s.nullable(s.string()),
  approval: s.nullable(s.string()),
  seeded: s.boolean(),
  locked: s.boolean(),
  inherits: s.nullable(s.array(s.string())),
  own: s.nullable(s.array(s.string())),
  allRows: s.nullable(s.array(s.string())),
});
export type RbacNewRolePlatformCreate = Infer<typeof RBAC_NEW_ROLE_PLATFORM_CREATE>;
// </contract rbac.new-role.platform-create>

// <request rbac.new-role.platform-create>
/** POST /api/admin/rbac/roles sends RbacRoleCreate (PlatformRbacController#createRole, rbac.role:create). Generated by widgets:contract. */
export const RBAC_NEW_ROLE_PLATFORM_CREATE_REQUEST = s.object('RbacRoleCreate', {
  name: s.nullable(s.string()),
  description: s.nullable(s.string()),
  kind: s.nullable(s.string()),
  inherits: s.nullable(s.array(s.string())),
  permissions: s.nullable(s.array(s.string())),
});
export type RbacNewRolePlatformCreateRequest = Infer<typeof RBAC_NEW_ROLE_PLATFORM_CREATE_REQUEST>;
// </request rbac.new-role.platform-create>

// <request rbac.new-role.org-create>
/** POST /api/orgs/{id}/roles sends OrgRoleBody (OrgAccessController#createRole, rbac.role:create). Generated by widgets:contract. */
export const RBAC_NEW_ROLE_ORG_CREATE_REQUEST = s.object('OrgRoleBody', {
  name: s.nullable(s.string()),
  description: s.nullable(s.string()),
  baseRoles: s.nullable(s.array(s.string())),
  permissions: s.nullable(s.array(s.string())),
});
export type RbacNewRoleOrgCreateRequest = Infer<typeof RBAC_NEW_ROLE_ORG_CREATE_REQUEST>;
// </request rbac.new-role.org-create>

// ---------------------------------------------------------------- hand-written (untyped on the server)

/** One widget as the registry serves it (WidgetRegistryService#active: the registered manifest + bundle). */
const REGISTERED_WIDGET = s.object('RegisteredWidget', {
  id: s.string(),
  version: s.string(),
  label: s.string(),
  description: s.nullable(s.string()),
  category: s.nullable(s.string()),
  contexts: s.array(s.string()),
  requires: s.array(s.string()),
  actions: s.array(s.object('WidgetAction', { id: s.string(), label: s.string(), cell: s.string(), command: s.nullable(s.string()) })),
  sources: s.array(s.string()),
  commands: s.array(s.string()),
  // null for widgets registered before operations existed (2026-11-15): none of the four can be ticked
  operations: s.nullable(s.array(s.enum('view', 'create', 'modify', 'approve'))),
  commandOperations: s.nullable(s.map(s.enum('create', 'modify', 'approve'))),
  bundle: s.nullable(s.string()),
  registeredAt: s.nullable(s.dateTime()),
});

/** GET /api/ui/widgets?portal= (PLATFORM, admin.access:read) and GET /api/orgs/{id}/ui/widgets?portal=
 *  (org portals, rbac.role:read): List<Map<String,Object>> on the server. */
export const RBAC_NEW_ROLE_WIDGETS = s.array(REGISTERED_WIDGET);
export type RbacNewRoleWidgets = Infer<typeof RBAC_NEW_ROLE_WIDGETS>;

/** A role as RBAC shows it inside an org (rbac-api.ts RbacRole). */
const ORG_ROLE = s.object('OrgRole', {
  name: s.string(),
  description: s.nullable(s.string()),
  kind: s.nullable(s.string()),
  base_roles: s.nullable(s.array(s.string())),
  permissions: s.array(s.string()),
});

/** GET /api/orgs/{id}/roles (OrgAccessController#roles, rbac.role:read): Map<String,Object> on the server. */
export const RBAC_NEW_ROLE_ORG_ROLES = s.object('OrgRolesView', {
  roles: s.array(ORG_ROLE),
  org_roles: s.array(ORG_ROLE),
  rbac_mode: s.nullable(s.string()),
});

/** The roles a new role may build on: platform roles (PLATFORM) or the org's view (org portals). */
export const RBAC_NEW_ROLE_ROLES = s.oneOf(RBAC_NEW_ROLE_PLATFORM_ROLES, RBAC_NEW_ROLE_ORG_ROLES);
export type RbacNewRoleRoles = Infer<typeof RBAC_NEW_ROLE_ROLES>;
export type RbacNewRoleOrgRoles = Infer<typeof RBAC_NEW_ROLE_ORG_ROLES>;

/** POST answers: RbacRoleView (PLATFORM) or the created org role (org portals, untyped map). */
export const RBAC_NEW_ROLE_CREATE = s.oneOf(RBAC_NEW_ROLE_PLATFORM_CREATE, ORG_ROLE);
/** POST bodies: RbacRoleCreate (PLATFORM) or OrgRoleBody (org portals). */
export const RBAC_NEW_ROLE_CREATE_REQUEST = s.oneOf(RBAC_NEW_ROLE_PLATFORM_CREATE_REQUEST, RBAC_NEW_ROLE_ORG_CREATE_REQUEST);
